struct Frame {
    std::optional<Point> position;
    std::optional<Point> press;
    bool down = false;
    bool cancelled = false;
};

if (frame.position)
    input.position = window_to_logical(layout, current_window_point);
if (frame.press)
    input.press = window_to_logical(layout, press_window_point);

const auto result = study_ui::button(start_bounds, pointer);
const bool start_clicked = app.screen() == Screen::menu && result.activated;
// 여기서 한 번만 Application의 confirm에 합친다.
app.advance(dt, gameplay_input, keyboard_confirm || start_clicked,
            keyboard_back, gameplay_keys_released);

Frame snapshot() const noexcept {
    if (cancelled_)
        return {std::nullopt, std::nullopt, false, true};
    return {position_, press_, down_, false};
}

button.image.tint = start_button.held
    ? Tint{.12f,.23f,.40f,1}
    : start_button.hovered
        ? Tint{.24f,.38f,.60f,1}
        : Tint{.15f,.22f,.35f,1};
